export declare const inspectorStyles = "\n/* ---- \u5C5E\u6027\u680F\u5BB9\u5668\u4E0E\u63A7\u4EF6 ---- */\n.wf-inspector {\n  flex: none;\n  width: auto;\n  height: 100%;\n  max-height: 100%;\n  display: flex;\n  flex-direction: column;\n  background: var(--wf-layer);\n  overflow: hidden;\n  min-height: 0;\n}\n\n.wf-inspector__scroll {\n  flex: 1 1 0;\n  height: 0;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  padding: 15px;\n  display: flex;\n  flex-direction: column;\n  gap: 11px;\n  scrollbar-width: thin;\n}\n\n.wf-inspector__scroll>* {\n  flex-shrink: 0;\n}\n\n.wf-inspector.is-collapsed {\n  visibility: hidden;\n  pointer-events: none;\n  padding: 0;\n  width: 0 !important;\n}\n\n.wf-inspector h3 {\n  margin: 0;\n  font-size: 14px;\n  color: var(--wf-ink);\n}\n\n.wf-inspector label {\n  display: grid;\n  gap: 4px;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n}\n\n.wf-inspector input,\n.wf-inspector select,\n.wf-inspector textarea {\n  width: 100%;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n}\n\n.wf-inspector input:focus,\n.wf-inspector select:focus,\n.wf-inspector textarea:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-inspector textarea {\n  min-height: 92px;\n  resize: none;\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 11px;\n  line-height: 1.55;\n}\n\n.wf-inspector__footer {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--wf-border);\n  background: var(--wf-layer);\n}\n\n.wf-inspector__footer .wf-btn {\n  font-size: 11px;\n  padding: 5px 11px;\n}\n\n.wf-inspector .wf-empty {\n  color: var(--wf-ink-2);\n  font-size: 12px;\n}\n\n.wf-field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n/* \u5B57\u6BB5\u4E0E\u8868\u5355\u884C\u5E03\u5C40\uFF08\u5C5E\u6027\u680F\u8868\u5355\u5171\u7528\uFF1B\u6B64\u524D\u6563\u843D\u5728\u5404\u8868\u5355\u7684\u5185\u8054 style\uFF09 */\n.wf-field--gap6 {\n  gap: 6px;\n}\n\n.wf-form-stack {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.wf-form-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-form-grid-1 {\n  display: grid;\n  gap: 8px;\n}\n\n.wf-form-grid-2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n}\n\n.wf-form-grid-wide {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 8px;\n}\n\n.wf-form-preline {\n  white-space: pre-line;\n}\n\n.wf-form-check {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  justify-content: flex-start;\n}\n\n/* \u590D\u9009\u6846\u9700\u8986\u76D6 .wf-inspector input{width:100%}\uFF08\u5426\u5219\u88AB\u6491\u6210\u5927\u65B9\u6846\u3001\u4E0D\u8D34\u8FB9\uFF09 */\n.wf-inspector .wf-form-check__box {\n  width: auto;\n  flex: 0 0 auto;\n  padding: 0;\n  margin: 0;\n  min-width: 0;\n  accent-color: var(--wf-brand);\n}\n\n/* ---- \u590D\u9009\u6E05\u5355 / \u63D0\u793A / \u9AD8\u7EA7\u6298\u53E0 / \u8DEF\u5F84\u5C55\u793A ---- */\n.wf-check-list__row {\n  justify-content: space-between;\n}\n\n.wf-btn--xs {\n  font-size: 9px;\n  padding: 2px 6px;\n}\n\n.wf-check-list {\n  max-height: 190px;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 6px;\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  scrollbar-width: thin;\n}\n\n.wf-check-list label {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--wf-ink);\n  font-size: 11px;\n}\n\n.wf-hint {\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-advanced {\n  border: 1px solid var(--wf-border);\n  border-radius: 9px;\n  background: var(--wf-layer-2);\n  padding: 0 9px;\n  margin: 12px 0 0;\n}\n\n.wf-advanced summary {\n  cursor: pointer;\n  padding: 8px 0;\n  color: var(--wf-ink-2);\n  font-size: 11px;\n  font-weight: 650;\n}\n\n.wf-advanced__content {\n  display: grid;\n  gap: 9px;\n  padding: 0 0 10px;\n}\n\n.wf-pathbox {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 9px 10px;\n  border: 1px solid var(--wf-border);\n  border-radius: 9px;\n  background: var(--wf-layer-2);\n}\n\n.wf-pathbox__label {\n  font-size: 10px;\n  color: var(--wf-ink-2);\n}\n\n.wf-pathbox__value {\n  font: 10px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;\n  color: var(--wf-ink);\n  word-break: break-all;\n}\n\n/* ---- \u56FE\u6807\u6309\u94AE\u4E0E\u7AD6\u5411\u5206\u9694\u6761 ---- */\n.wf-iconbtn {\n  width: 32px;\n  height: 32px;\n  padding: 0;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 16px;\n}\n\n.wf-splitter {\n  position: relative;\n  z-index: 12;\n  flex: none;\n  min-width: 9px;\n  width: 9px;\n  cursor: col-resize;\n  touch-action: none;\n  background: var(--wf-layer);\n  outline: 0;\n}\n\n.wf-splitter::before {\n  content: \"\";\n  position: absolute;\n  inset: 0 3px;\n  background: var(--wf-border);\n}\n\n.wf-splitter:hover::before,\n.wf-splitter:focus-visible::before,\n.wf-splitter.is-dragging::before {\n  inset: 0 2px;\n  background: var(--wf-brand);\n}\n";
